-- 2) Email identities (so the accounts can sign in)
insert into auth.identities (id, user_id, identity_data, provider, provider_id, last_sign_in_at, created_at, updated_at)
select gen_random_uuid(), u.id, jsonb_build_object('sub', u.id::text, 'email', u.email), 'email', u.id::text, now(), now(), now() from auth.users u where u.email like '%@gmail.com' and not exists (select 1 from auth.identities i where i.user_id = u.id);

